/// or more keys are equal, the resulting map uses the value of the rightmost entry.
#[macro_export]
macro_rules! imap {
    [$($tail:tt)*] => {
        $crate::vstd::prelude::verus_proof_macro_exprs!($crate::vstd::imap::imap_internal!($($tail)*))
    };
}

