            assert(post.combiner.is_Responding());
            let post_elems = post.combiner.get_Responding_elems();
            let post_idx = post.combiner.get_Responding_idx();
            assert(post_elems.len() == post.num_clients);
            assert(0 <= post_idx);
            assert(post_idx <= post.num_clients);

            // Prove combiner_has_inv in post state
            // Pick an arbitrary i and show the implication holds
            assert(forall |i: nat| #[trigger] post.combiner_has(i) ==>
                post.client_waiting(i)
                && post.slots.index(i)
                && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
