                // In pre state (Collecting with elems where len == num_clients):
                //   pre.combiner_has(i) = valid_idx(i) && i < pre.elems.len() && pre.elems[i].is_Some()
                //                     = i < num_clients && i < num_clients && pre.elems[i].is_Some()
                //                     = i < num_clients && pre.elems[i].is_Some()

                // In post state (Responding with idx=0):
                //   post.combiner_has(i) = valid_idx(i) && i >= 0 && post.elems[i].is_Some()
                //                        = i < num_clients && true && pre.elems[i].is_Some()  (since post.elems == pre.elems)
                //                        = i < num_clients && pre.elems[i].is_Some()

                // So combiner_has is preserved!

                // Similarly for client_waiting, slots, requests, responses: all unchanged

                // The key lemmas we need:

                // Lemma: valid_idx is preserved
                assert(forall |i: nat| post.valid_idx(i) ==> pre.valid_idx(i)) by {
                    // valid_idx only depends on num_clients, which doesn't change
                    open spec fn valid_idx(self: Self, i: nat) -> bool { 0 <= i && i < self.num_clients }
                    assert(post.num_clients == pre.num_clients);
                    assert(forall |i: nat| (0 <= i && i < post.num_clients) <==> (0 <= i && i < pre.num_clients));
                };

                // Lemma: clients is unchanged
                assert(post.clients =~= pre.clients);

                // Lemma: slots is unchanged
                assert(post.slots =~= pre.slots);

                // Lemma: requests is unchanged
                assert(post.requests =~= pre.requests);

                // Lemma: responses is unchanged
                assert(post.responses =~= pre.responses);

                // Lemma: combiner elems is unchanged
                assert(post.combiner.get_Responding_elems() =~= pre.combiner.get_Collecting_elems());

                // Now prove the invariant
                open spec fn combiner_has(self: Self, i: nat) -> bool {
                    self.valid_idx(i)
                    && match self.combiner {
                        Combiner::Collecting{elems} => i < elems.len() && elems.index(i as int).is_Some(),
                        Combiner::Responding{elems, idx} => i >= idx && elems.index(i as int).is_Some(),
                    }
                }

                open spec fn client_waiting(self: Self, i: nat) -> bool {
                    self.valid_idx(i)
                    && self.clients.index(i) == Client::Waiting { rid: _ }
                }

                open spec fn combiner_rid(self: Self, i: nat) -> int {
                    match self.combiner {
                        Combiner::Collecting{elems} => elems.index(i as int).get_Some_0(),
                        Combiner::Responding{elems, idx} => elems.index(i as int).get_Some_0(),
                    }
                }

                open spec fn request_stored(self: Self, i: nat) -> bool {
                    self.requests.dom().contains(i)
                }

                assert(post.clients =~= pre.clients);
                assert(post.slots =~= pre.slots);
                assert(post.requests =~= pre.requests);
                assert(post.responses =~= pre.responses);
                assert(post.combiner.get_Responding_elems() =~= pre.combiner.get_Collecting_elems());

                // The key equality: combiner_has is preserved
                // For valid indices, combiner_has has the same meaning in both states
                assert(forall |i: nat| post.valid_idx(i) ==>
                    post.combiner_has(i) <==> pre.combiner_has(i)) by {
                    assert(post.num_clients == pre.num_clients);
                    assert(post.combiner.get_Responding_elems() =~= pre.combiner.get_Collecting_elems());
                    // In pre state: pre.combiner_has(i) = i < num_clients && pre.elems[i].is_Some()
                    // In post state: post.combiner_has(i) = i >= 0 && post.elems[i].is_Some()
                    //                = true && pre.elems[i].is_Some()  (for nat i)
                    // But we also need i < num_clients from valid_idx
                    //Actually, the issue is more subtle:
                    // pre.combiner_has(i) = valid_idx(i) && i < len && elems[i].is_Some()
                    //                     = (i < num_clients) && (i < num_clients) && elems[i].is_Some()
                    //                     = i < num_clients && elems[i].is_Some()
                    // post.combiner_has(i) = valid_idx(i) && i >= 0 && elems[i].is_Some()
                    //                      = (i < num_clients) && true && elems[i].is_Some()
                    //                      = i < num_clients && elems[i].is_Some()
                    // So they are equal!
                };
            };
        }

        transition!{
            combiner_go_to_collecting() {
                require(pre.combiner.is_Responding());
                require(pre.combiner.get_Responding_idx() == pre.num_clients);
                update combiner = Combiner::Collecting{ elems: Seq::empty() };
            }
        }

        #[inductive(combiner_go_to_collecting)]
        fn combiner_go_to_collecting_inductive(pre: Self, post: Self) {
            admit()
        }

    }
}

fn main() {}

