    assert(post.combiner.is_Responding());
    assert(post.combiner.get_Responding_elems().len() == post.num_clients);
    assert(0 <= post.combiner.get_Responding_idx());
    assert(post.combiner.get_Responding_idx() <= post.num_clients);

