    assert(pre.clients =~= post.clients);
    assert(pre.slots =~= post.slots);
    assert(pre.requests =~= post.requests);
    assert(pre.responses =~= post.responses);
    assert(pre.combiner.get_Collecting_elems() =~= post.combiner.get_Responding_elems());

    // Verify clients_size for post state:
    assert(post.combiner.is_Responding());
    assert(post.combiner.get_Responding_elems().len() == post.num_clients);
    assert(0 <= post.combiner.get_Responding_idx());
    assert(post.combiner.get_Responding_idx() <= post.num_clients);

    // Prove not_waiting_inv in post state:
    // Since clients, slots, and num_clients don't change, and valid_idx only depends on num_clients:
    open spec fn valid_idx(self: Self, i: nat) -> bool { 0 <= i && i < self.num_clients }
    open spec fn not_waiting_inv(self: Self) -> bool {
        forall |i: nat| #[trigger] valid_idx(self, i) && self.clients.index(i) == Client::Idle ==> !self.slots.index(i)
    }
    // valid_idx(pre, i) <==> valid_idx(post, i) because num_clients is unchanged
    // clients[pre, i] == clients[post, i] because clients unchanged
    // slots[pre, i] == slots[post, i] because slots unchanged
    // So not_waiting_inv(pre) <==> not_waiting_inv(post)
    // Since not_waiting_inv(pre) holds (by invariant hypothesis), not_waiting_inv(post) holds.

    // Prove waiting_inv in post state:
    open spec fn client_waiting(self: Self, i: nat) -> bool {
        valid_idx(self, i) && self.clients.index(i) == Client::Waiting { rid: _ }
    }
    open spec fn waiting_inv(self: Self) -> bool {
        forall |i: nat| #[trigger] client_waiting(self, i) ==>
            self.request_stored(i) || self.response_stored(i) || self.combiner_has(i)
